import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNextInt()) return;

        int n = sc.nextInt();
        int reqP = 0;
        int reqM = 0;

        for (int i = 0; i < n; i++) {
            int t = sc.nextInt();
            if (t == 1) {
                reqP++;
            } else if (t == 2) {
                reqM++;
            }
        }

        int p = sc.nextInt();
        int m = sc.nextInt();

        if (reqP <= p && reqM <= m) {
            System.out.println("S");
        } else {
            System.out.println("N");
        }
    }
}
